835:   let current = primary;
836:   for (let jump = 0; jump < maxJumps; jump += 1) {
837:     let next = null;
838:     let nearest = jumpRange;
839:     for (const candidate of world.zombies) {
840:       if (hit.has(candidate)) continue;
841:       const distance = dist(current.x, current.y, candidate.x, candidate.y);
842:       if (distance < nearest) { nearest = distance; next = candidate; }
843:     }
844:     if (!next) break;
845:     hit.add(next);
846:     createLightning(current, next, player.chainLevel);
847:     damageZombie(next, player.damage * (0.62 + player.chainLevel * 0.08));
848:     next.hitFlash = 0.12;
849:     if (next.hp <= 0) defeatZombie(next, world.zombies.indexOf(next));
850:     current = next;
851:   }
852: }
