      if (hud.debugOverlay.classList.contains('hidden')) openDebugMenu();
      else closeDebugMenu();
    }
    return;
  }
  if (key === 'escape') {
    if (!hud.debugOverlay.classList.contains('hidden')) closeDebugMenu();
    else if (!event.repeat) togglePause();
    return;
  }
  if (key === 'p') {
    if (!event.repeat) togglePause();
    return;
  }

