import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
try {
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.locator('#startButton').click();
  await page.waitForFunction(() => world.running && !world.paused);
  await page.locator('#debugButton').click();
  await page.waitForFunction(() => world.paused && !document.querySelector('#debugOverlay').classList.contains('hidden'));
  const types = await page.locator('#debugZombieSelect option').count();
  const upgrades = await page.locator('#debugUpgradeSelect option').count();
  if (types < 4 || upgrades < 1) throw new Error(`Controls not populated: ${types} types, ${upgrades} upgrades`);
  await page.locator('#debugZombieSelect').selectOption('toxic');
  await page.locator('#debugSpawnButton').click();
  await page.waitForFunction(() => world.zombies.filter(z => z.isDebug).length === 1);
  await page.locator('#debugCompareButton').click();
  await page.waitForFunction(() => world.zombies.filter(z => z.isDebug).length === document.querySelectorAll('#debugZombieSelect option').length + 1);
  await page.locator('#debugUpgradeSelect').selectOption({ index: 0 });
  await page.locator('#debugApplyUpgradeButton').click();
  await page.locator('#debugHealButton').click();
  await page.locator('#debugResetPlayerButton').click();
  const rewardCheck = await page.evaluate(() => {
    const zombie = world.zombies.find(z => z.isDebug);
    const before = { score: world.score, kills: world.kills, xp: world.player.xp };
    defeatZombie(zombie, world.zombies.indexOf(zombie));
    return { before, after: { score: world.score, kills: world.kills, xp: world.player.xp } };
  });
  if (JSON.stringify(rewardCheck.before) !== JSON.stringify(rewardCheck.after)) throw new Error('Debug zombie granted a reward/stat change');
  await page.locator('#debugClearButton').click();
  await page.keyboard.press('Escape');
  await page.waitForFunction(() => !world.paused && document.querySelector('#debugOverlay').classList.contains('hidden'));
  await page.keyboard.press('F2');
  await page.waitForFunction(() => world.paused && !document.querySelector('#debugOverlay').classList.contains('hidden'));
  await page.keyboard.press('Escape');
  await page.waitForFunction(() => !world.paused);
  mkdirSync('/tmp/opencode', { recursive: true });
  await page.screenshot({ path: '/tmp/opencode/zombie-siege-final.jpg', type: 'jpeg', quality: 82 });
  console.log(JSON.stringify({ types, upgrades, safeStats: rewardCheck.before, viewport: page.viewportSize(), errors }, null, 2));
  if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
} finally { await browser.close(); }

